import static com.watchreader.fanqie.ReaderPlugin.*;

/** Continuous reading and library UI on the real watch. Never writes real cloud positions. */
public final class LibraryUiInstrumentation extends Instrumentation {
    JSONArray checks=new JSONArray(),failures=new JSONArray();FanqieActivity activity;volatile String stage="start";
    void check(String name,boolean ok){if(!ok)throw new AssertionError(name);checks.put(name);}
    void main(Runnable action){runOnMainSync(action);waitForIdleSync();}
    Field field(String name)throws Exception{Field f=FanqieActivity.class.getDeclaredField(name);f.setAccessible(true);return f;}
    <T extends View> T find(View root,Class<T> type,String label){if(type.isInstance(root)&&(label==null||(root instanceof TextView&&((TextView)root).getText().toString().equals(label))))return type.cast(root);if(root instanceof ViewGroup){ViewGroup g=(ViewGroup)root;for(int i=0;i<g.getChildCount();i++){T result=find(g.getChildAt(i),type,label);if(result!=null)return result;}}return null;}
    View decor(){return activity.getWindow().getDecorView();}
    ReaderView reader(){return find(decor(),ReaderView.class,null);}
    void click(String name){main(()->{Button b=find(decor(),Button.class,name);if(b==null)throw new AssertionError("Missing button "+name);b.performClick();});}
    void await(BooleanSupplier ready)throws Exception{long end=System.currentTimeMillis()+45000;while(System.currentTimeMillis()<end){final boolean[] ok={false};main(()->ok[0]=ready.getAsBoolean());if(ok[0])return;Thread.sleep(150);}throw new IOException("UI timeout at "+stage);}
    void waitButton(String name)throws Exception{await(()->find(decor(),Button.class,name)!=null);}
    void flip(boolean forward){main(()->{ReaderView v=reader();long now=SystemClock.uptimeMillis();float x=v.getWidth()*(forward?.8f:.2f),y=v.getHeight()*.5f;MotionEvent down=MotionEvent.obtain(now,now,0,x,y,0),up=MotionEvent.obtain(now,now+20,1,x,y,0);v.dispatchTouchEvent(down);v.dispatchTouchEvent(up);down.recycle();up.recycle();});}
    void end(){main(()->reader().restoreToEnd());}
    void awaitChapter(String item)throws Exception{await(()->reader()!=null&&activity.current.itemId.equals(item));Thread.sleep(250);}
    void shot(String name)throws Exception{android.graphics.Bitmap bitmap=getUiAutomation().takeScreenshot();if(bitmap!=null)try(FileOutputStream output=new FileOutputStream(new File(getTargetContext().getFilesDir(),name+".png"))){bitmap.compress(android.graphics.Bitmap.CompressFormat.PNG,100,output);}}
    @Override public void onCreate(Bundle args){super.onCreate(args);start();}
    @Override public void onStart(){java.util.concurrent.ScheduledExecutorService watchdog=java.util.concurrent.Executors.newSingleThreadScheduledExecutor();watchdog.schedule(()->{Bundle b=new Bundle();b.putString("timeout",stage);finish(0,b);},240,java.util.concurrent.TimeUnit.SECONDS);try{
        Context ctx=getTargetContext();activity=(FanqieActivity)startActivitySync(new Intent(ctx,FanqieActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK).putExtra("progress_test_readonly",true));
        stage="live-categories";FanqiePlugin real=new FanqiePlugin(new CredentialStore(ctx));List<ShelfGroup> groups=real.shelfGroups();check("live-account-groups-present",groups.size()>2&&groups.get(0).id.isEmpty());int sum=0;ShelfGroup small=null,large=null;for(ShelfGroup group:groups)if(!group.id.isEmpty()){sum+=group.count;if(group.count>20)large=group;else if(group.count>0)small=group;}check("group-counts-cover-entire-shelf",sum==groups.get(0).count);
        final ShelfGroup selected=small;Page<BookInfo> page=real.bookshelf(selected.id,"");check("category-filter-before-pagination",page.items.size()==selected.count&&!page.more);Page<BookInfo> first=real.bookshelf(large.id,"");Page<BookInfo> second=real.bookshelf(large.id,first.next);Set<String> ids=new HashSet<>();for(BookInfo b:first.items)ids.add(b.id);check("category-pagination-stays-in-group",first.more&&first.items.size()==20&&!second.items.isEmpty()&&second.items.stream().noneMatch(b->ids.contains(b.id)));check("different-groups-have-no-crossed-books",page.items.stream().noneMatch(b->ids.contains(b.id)));
        stage="live-details-cover";BookInfo live=new BookInfo("7134994653631220774","书籍详情测试","");BookDetails detail=real.details(live);check("live-book-details",detail.chapters>0&&!detail.description.isEmpty()&&!detail.book.title.equals(live.title));android.graphics.Bitmap image=CoverLoader.load(detail.coverUrl);check("live-cover-decodes-with-bounded-size",image.getWidth()>0&&Math.max(image.getWidth(),image.getHeight())<=700);image.recycle();for(String bad:Arrays.asList("http://p6-novel-sign.byteimg.com/a","https://evil.test/a","https://p6-novel-sign.byteimg.com.evil.test/a","https://user:pass@p6-novel-sign.byteimg.com/a","https://p6-novel-sign.byteimg.com:8080/a")){try{CoverLoader.checkedUrl(bad);throw new AssertionError("unsafe cover allowed");}catch(IOException expected){}}check("cover-rejects-unsafe-host-scheme-userinfo-port",true);
        stage="ui-categories";waitButton("书架分类");click("书架分类");String groupLabel=selected.name+" · "+selected.count;waitButton(groupLabel);click(groupLabel);waitButton("切换分类");BookInfo chosen=page.items.get(0);String label=chosen.title+(chosen.author.isEmpty()?"":"\n"+chosen.author);waitButton(label);click(label);waitButton("查看详情");check("book-opens-second-level-menu",find(decor(),Button.class,"章节目录")!=null&&find(decor(),Button.class,"查看封面")!=null);shot("library-book-menu");
        stage="ui-details";main(()->activity.bookActions(live));click("查看详情");waitButton("返回书籍菜单");check("details-shows-summary-and-count",find(decor(),TextView.class,detail.description)!=null&&find(decor(),TextView.class,"共 "+detail.chapters+" 章")!=null);shot("library-details");click("查看封面");await(()->find(decor(),ImageView.class,null)!=null);check("cover-is-visible-in-secondary-menu",true);shot("library-cover");
        stage="continuous-reading";Fake source=new Fake();main(()->{try{activity.plugin=source;field("bookId").set(activity,"99123");field("bookTitle").set(activity,"跨章测试");field("chapterIndex").setInt(activity,0);field("chapters").set(activity,source.chapters);activity.current=source.content(0);activity.showReader();}catch(Exception e){throw new RuntimeException(e);}});awaitChapter("991230");check("same-reader-class-as-local-txt",reader().getClass()==ReaderView.class);check("full-size-reader-preserved",reader().getWidth()==466&&reader().getHeight()==466);
        stage="exact-page-count";main(()->reader().restoreTo(0));await(()->reader().isPageCountExact());int total=reader().getPageCount();for(int i=1;i<total;i++){Thread.sleep(110);flip(true);check("page-never-exceeds-total-"+i,reader().getPageIndex()+1<=reader().getPageCount());}check("count-matches-actual-last-page",activity.current.itemId.equals("991230")&&reader().getPageIndex()+1==total&&reader().getPageCount()==total);shot("library-exact-last-page");main(()->{reader().setFontSize(18);reader().restoreTo(0);});await(()->reader().isPageCountExact());int resized=reader().getPageCount();check("font-size-recalculates-total",resized>total);for(int i=1;i<resized;i++){Thread.sleep(110);flip(true);}check("resized-last-page-matches-total",activity.current.itemId.equals("991230")&&reader().getPageIndex()+1==resized&&reader().getPageCount()==resized);main(()->{reader().setFontSize(15);reader().restoreTo(123);});await(()->reader().isPageCountExact());int restoredTotal=reader().getPageCount(),restoredPage=reader().getPageIndex();for(int i=restoredPage+1;i<restoredTotal;i++){Thread.sleep(110);flip(true);}check("paragraph-anchor-last-page-matches-total",activity.current.itemId.equals("991230")&&reader().getPageIndex()+1==restoredTotal&&reader().getPageCount()==restoredTotal);main(()->{try{field("entryOffset").set(activity,Integer.valueOf(0));activity.showReader();}catch(Exception e){throw new RuntimeException(e);}});awaitChapter("991230");stage="continuous-reading";end();int previousEnd=reader().getCharOffset();check("previous-chapter-has-multiple-pages",previousEnd>0);flip(true);awaitChapter("991231");check("last-page-flip-opens-next-chapter-at-start",reader().getCharOffset()==0);flip(false);awaitChapter("991230");check("chapter-start-backflip-opens-previous-last-page",reader().getCharOffset()==previousEnd);Thread.sleep(150);flip(true);awaitChapter("991231");end();Thread.sleep(150);flip(true);awaitChapter("991232");check("all-chapters-read-in-sequence",reader().getCharOffset()==0);end();Thread.sleep(150);int before=source.calls;flip(true);Thread.sleep(300);check("last-book-boundary-does-not-fetch-nonexistent-chapter",activity.current.itemId.equals("991232")&&source.calls==before);main(()->reader().restoreTo(0));Thread.sleep(150);flip(false);awaitChapter("991231");check("backward-navigation-is-continuous",reader().getCharOffset()>0);
        stage="failure-and-retry";source.fail=true;main(()->{try{((Map<?,?>)field("cache").get(activity)).clear();reader().restoreTo(0);}catch(Exception e){throw new RuntimeException(e);}});ReaderView old=reader();Thread.sleep(150);flip(false);Thread.sleep(900);check("network-error-preserves-current-page-and-reader",reader()==old&&activity.current.itemId.equals("991231")&&reader().getCharOffset()==0);source.fail=false;flip(false);awaitChapter("991230");check("failed-boundary-can-retry-by-turning-again",reader().getCharOffset()>0);
        stage="stale-boundary";source.delay=600;main(()->{try{((Map<?,?>)field("cache").get(activity)).clear();reader().restoreToEnd();}catch(Exception e){throw new RuntimeException(e);}});Thread.sleep(150);flip(true);main(()->activity.searchForm());Thread.sleep(900);check("stale-chapter-load-does-not-replace-opened-menu",find(decor(),EditText.class,null)!=null&&reader()==null);source.delay=0;
        stage="restore-account";main(()->{activity.plugin=real;activity.home();});waitButton("书架分类");
    }catch(Throwable e){failures.put(stage+": "+e.getClass().getSimpleName()+" "+e.getMessage());}finally{watchdog.shutdownNow();try{JSONObject result=new JSONObject().put("checks",checks).put("failures",failures).put("real_cloud_position_writes",0).put("real_public_posts",0);try(FileOutputStream out=new FileOutputStream(new File(getTargetContext().getFilesDir(),"test-report.json"))){out.write(result.toString(2).getBytes(StandardCharsets.UTF_8));}Bundle b=new Bundle();b.putString("summary","library checks="+checks.length()+" failures="+failures.length());b.putString("failures",failures.toString());finish(failures.length()==0?Activity.RESULT_OK:Activity.RESULT_CANCELED,b);}catch(Exception e){finish(0,new Bundle());}}}
    static final class Fake implements ReaderPlugin {
        List<ChapterInfo> chapters=Arrays.asList(new ChapterInfo("991230","测试第一章","v"),new ChapterInfo("991231","测试第二章","v"),new ChapterInfo("991232","测试第三章","v"));volatile int calls;volatile boolean fail;volatile long delay;
        ChapterContent content(int chapter){List<Paragraph> paras=new ArrayList<>();for(int i=0;i<55;i++)paras.add(new Paragraph(i,"第"+(chapter+1)+"章，第"+i+"段。用于验证连续阅读，共用原来的翻页、表冠、字号和分页逻辑。"));return new ChapterContent("99123",chapters.get(chapter).id,chapters.get(chapter).title,"v",paras);}
        public String id(){return "test";}public Page<BookInfo> bookshelf(String c){return new Page<>(Collections.emptyList(),"",false);}public Page<BookInfo> search(String k,String c){return bookshelf(c);}public List<ChapterInfo> directory(String b){return chapters;}public ChapterContent chapter(String b,ChapterInfo c)throws Exception{calls++;Thread.sleep(delay);if(fail)throw new IOException("offline mock");return content(chapters.indexOf(c));}public Page<Comment> comments(ChapterContent c,Paragraph p,String next){return new Page<>(Collections.emptyList(),"",false);}public String publish(ChapterContent c,Paragraph p,String t){throw new AssertionError("No posting");}
    }
}
